$err='';$msg='';$id=(int)($_GET['id']??$_POST['id']??0);
function count_access(array $s): bool {return is_super_admin() || can_access_location((int)$s['location_id']);}
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_check();$action=$_POST['action']??'';
 try{
  if($action==='create'){
   $loc=(int)($_POST['location_id']??0);if(!$loc||!can_access_location($loc))throw new Exception('Location not allowed.');
   db()->beginTransaction();$no='CNT-'.date('Ymd-His').'-'.random_int(100,999);
   $st=db()->prepare("INSERT INTO stock_count_sessions(count_no,location_id,status,notes,started_by) VALUES(?,?,'OPEN',?,?)");$st->execute([$no,$loc,trim($_POST['notes']??''),current_user()['id']]);$sid=(int)db()->lastInsertId();
   $st=db()->prepare("INSERT INTO stock_count_lines(session_id,product_id,batch_id,system_qty,counted_qty,serial_tracking) SELECT ?,ib.product_id,ib.batch_id,ib.qty,0,p.serial_tracking FROM inventory_balances ib JOIN products p ON p.id=ib.product_id WHERE ib.location_id=? AND ib.qty>0");$st->execute([$sid,$loc]);
   db()->commit();audit('STOCK_COUNT_CREATE','stock_count',$sid);redirect('stock_count.php?id='.$sid);
  }
  $st=db()->prepare('SELECT * FROM stock_count_sessions WHERE id=?');$st->execute([$id]);$s=$st->fetch();if(!$s||!count_access($s))throw new Exception('Stock count not found / outside scope.');
  if($action==='scan'){
   if($s['status']!=='OPEN')throw new Exception('Count is not open.');$barcode=trim($_POST['barcode']??'');if($barcode==='')throw new Exception('Scan barcode.');
   db()->beginTransaction();
   $st=db()->prepare("SELECT ps.id serial_id,ps.product_id,ps.batch_id,ps.status,p.serial_tracking FROM product_serials ps JOIN products p ON p.id=ps.product_id WHERE ps.serial_barcode=? AND ps.location_id=? AND ps.status IN ('AVAILABLE','RESERVED') FOR UPDATE");$st->execute([$barcode,$s['location_id']]);$r=$st->fetch();
   if($r){$st=db()->prepare('SELECT id FROM stock_count_lines WHERE session_id=? AND product_id=? AND batch_id=? FOR UPDATE');$st->execute([$id,$r['product_id'],$r['batch_id']]);$line=$st->fetchColumn();if(!$line)throw new Exception('Barcode belongs to stock outside count snapshot.');$st=db()->prepare('SELECT 1 FROM stock_count_scans WHERE session_id=? AND barcode=?');$st->execute([$id,$barcode]);if($st->fetchColumn())throw new Exception('ALREADY COUNTED — this piece was already scanned in this count. Do not count it again.');$st=db()->prepare('INSERT INTO stock_count_scans(session_id,line_id,barcode,serial_id,scanned_by) VALUES(?,?,?,?,?)');$st->execute([$id,$line,$barcode,$r['serial_id'],current_user()['id']]);db()->prepare('UPDATE stock_count_lines SET counted_qty=counted_qty+1,last_counted_by=?,last_counted_at=NOW() WHERE id=?')->execute([current_user()['id'],$line]);}
   else{$st=db()->prepare("SELECT scl.id,p.serial_tracking FROM stock_count_lines scl JOIN batches b ON b.id=scl.batch_id JOIN products p ON p.id=scl.product_id WHERE scl.session_id=? AND (b.batch_barcode=? OR p.product_barcode=?) ORDER BY b.purchased_at LIMIT 1 FOR UPDATE");$st->execute([$id,$barcode,$barcode]);$line=$st->fetch();if(!$line)throw new Exception('Barcode not found in this location count.');if((int)$line['serial_tracking']===1)throw new Exception('Serialized product: scan the individual unique garment barcode.');db()->prepare('UPDATE stock_count_lines SET counted_qty=counted_qty+1,last_counted_by=?,last_counted_at=NOW() WHERE id=?')->execute([current_user()['id'],$line['id']]);}
   db()->commit();$msg='Counted: '.$barcode;
  }elseif($action==='set_qty'){
   if($s['status']!=='OPEN')throw new Exception('Count is not open.');$line=(int)($_POST['line_id']??0);$qty=max(0,(float)($_POST['counted_qty']??0));$st=db()->prepare('SELECT serial_tracking FROM stock_count_lines WHERE id=? AND session_id=?');$st->execute([$line,$id]);$serial=$st->fetchColumn();if($serial===false)throw new Exception('Count line not found.');if((int)$serial===1)throw new Exception('Serialized garments must be counted by unique barcode scan.');db()->prepare('UPDATE stock_count_lines SET counted_qty=?,last_counted_by=?,last_counted_at=NOW() WHERE id=?')->execute([$qty,current_user()['id'],$line]);$msg='Manual batch quantity saved.';
  }elseif($action==='submit'){
   if($s['status']!=='OPEN')throw new Exception('Only OPEN count can be submitted.');db()->prepare("UPDATE stock_count_sessions SET status='SUBMITTED',submitted_by=?,submitted_at=NOW() WHERE id=?")->execute([current_user()['id'],$id]);audit('STOCK_COUNT_SUBMIT','stock_count',$id);publish_event('STOCK_COUNT_SUBMITTED','Physical stock count submitted',$s['count_no'].' · review variance',['super_admin','manager'],'stock_count',$id,$s['location_id']);$msg='Count submitted for approval.';
  }elseif($action==='approve'){
   if(!is_super_admin() && (current_user()['role']??'')!=='manager')throw new Exception('Manager/Super Admin approval required.');if($s['status']!=='SUBMITTED')throw new Exception('Only SUBMITTED count can be approved.');if(!is_super_admin() && (int)$s['started_by']===(int)current_user()['id'])throw new Exception('Manager cannot approve a count started by the same user. Super Admin or another authorised Manager must approve it.');db()->prepare("UPDATE stock_count_sessions SET status='APPROVED',approved_by=?,approved_at=NOW() WHERE id=?")->execute([current_user()['id'],$id]);audit('STOCK_COUNT_APPROVE','stock_count',$id);publish_event('STOCK_COUNT_APPROVED','Physical stock count approved',$s['count_no'].' · variance approved for review',['super_admin','manager','godown'],'stock_count',$id,$s['location_id']);$msg='Count approved. Variances are documented; stock is NOT auto-adjusted.';
  }else throw new Exception('Invalid action.');
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$err=user_error_message($e,'ALREADY COUNTED — this piece was already scanned in this count.');
  // Keep a record of every rejected scan (unexpected / wrong location / duplicate) so the reviewer can see it.
  if(($action??'')==='scan'&&!empty($s)&&$s['status']==='OPEN'&&trim((string)($_POST['barcode']??''))!==''){try{db()->prepare('INSERT INTO stock_count_exceptions(session_id,barcode,reason,scanned_by) VALUES(?,?,?,?)')->execute([$id,mb_substr(trim((string)$_POST['barcode']),0,100),mb_substr($err,0,255),current_user()['id']]);}catch(Throwable $e2){}}}
}
if(!$id){$locs=[];if(is_super_admin())$locs=db()->query('SELECT id,code,name,rack,shelf_bin FROM locations WHERE active=1 ORDER BY code')->fetchAll();else{$ids=assigned_location_ids();if($ids){$ph=implode(',',array_fill(0,count($ids),'?'));$st=db()->prepare("SELECT id,code,name,rack,shelf_bin FROM locations WHERE active=1 AND id IN ($ph) ORDER BY code");$st->execute($ids);$locs=$st->fetchAll();}}
 [$scope,$params]=location_scope_sql('s.location_id');$st=db()->prepare("SELECT s.*,l.code,l.name,u.name started_name FROM stock_count_sessions s JOIN locations l ON l.id=s.location_id JOIN users u ON u.id=s.started_by WHERE 1=1".$scope.' ORDER BY s.id DESC LIMIT 200');$st->execute($params);$sessions=$st->fetchAll();page_header('Physical Stock Count / Cycle Count');if($err)echo '<div class="notice error">'.e($err).'</div>';if($msg)echo '<div class="notice success">'.e($msg).'</div>';?>
 <form method="post" class="panel"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><div class="row"><div><label>Location</label><select name="location_id" required><?php foreach($locs as $l):?><option value="<?=$l['id']?>"><?=e($l['code'].' · '.$l['name'].' · '.$l['rack'].'/'.$l['shelf_bin'])?></option><?php endforeach;?></select></div><div><label>Notes</label><input name="notes"></div></div><br><button class="btn">START NEW COUNT</button></form><br>
