$st=db()->prepare('SELECT s.*,l.code,l.name,l.rack,l.shelf_bin FROM stock_count_sessions s JOIN locations l ON l.id=s.location_id WHERE s.id=?');$st->execute([$id]);$s=$st->fetch();if(!$s||!count_access($s)){http_response_code(403);exit('Count outside scope.');}
$st=db()->prepare("SELECT scl.*,p.sku,p.product_name,p.color,p.size,p.product_image,b.batch_no,b.batch_barcode,(scl.counted_qty-scl.system_qty) variance FROM stock_count_lines scl JOIN products p ON p.id=scl.product_id JOIN batches b ON b.id=scl.batch_id WHERE scl.session_id=? ORDER BY p.product_name,b.batch_no");$st->execute([$id]);$lines=$st->fetchAll();
